CREATE TABLE users (id BIGINT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(80) NOT NULL, password_hash VARCHAR(100) NOT NULL, display_name VARCHAR(120) NOT NULL, role VARCHAR(20) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, force_password_change BOOLEAN NOT NULL DEFAULT TRUE, last_login_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT uk_users_username UNIQUE(username), CONSTRAINT ck_users_role CHECK(role IN ('OWNER','ADMIN','STAFF')));
CREATE TABLE business_settings (id BIGINT PRIMARY KEY, gym_name VARCHAR(160) NOT NULL, phone VARCHAR(30), email VARCHAR(160), address VARCHAR(500), currency VARCHAR(3) NOT NULL DEFAULT 'INR', time_zone VARCHAR(60) NOT NULL DEFAULT 'Asia/Kolkata', logo_url VARCHAR(500), receipt_footer VARCHAR(500), tax_identifier VARCHAR(80), reminder_days INT NOT NULL DEFAULT 7, allow_multiple_daily_checkins BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE membership_plans (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, duration_months INT NOT NULL, price DECIMAL(12,2) NOT NULL, description VARCHAR(500), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT uk_plan_name UNIQUE(name), CONSTRAINT ck_plan_duration CHECK(duration_months > 0), CONSTRAINT ck_plan_price CHECK(price >= 0));
CREATE TABLE members (id BIGINT AUTO_INCREMENT PRIMARY KEY, member_code VARCHAR(30) NOT NULL, name VARCHAR(160) NOT NULL, phone VARCHAR(30), email VARCHAR(160), gender VARCHAR(30), date_of_birth DATE, address VARCHAR(500), emergency_contact VARCHAR(120), join_date DATE NOT NULL, plan_id BIGINT, membership_start_date DATE, expiry_date DATE, status VARCHAR(20) NOT NULL, notes VARCHAR(1000), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT uk_member_code UNIQUE(member_code), CONSTRAINT uk_member_phone UNIQUE(phone), CONSTRAINT uk_member_email UNIQUE(email), CONSTRAINT fk_member_plan FOREIGN KEY(plan_id) REFERENCES membership_plans(id), INDEX ix_member_name(name), INDEX ix_member_status_expiry(status,expiry_date));
CREATE TABLE payments (id BIGINT AUTO_INCREMENT PRIMARY KEY, receipt_number VARCHAR(40) NOT NULL, member_id BIGINT NOT NULL, plan_id BIGINT, plan_name_snapshot VARCHAR(100) NOT NULL, period_start DATE NOT NULL, period_end DATE NOT NULL, payment_date TIMESTAMP NOT NULL, amount DECIMAL(12,2) NOT NULL, method VARCHAR(30) NOT NULL, reference_note VARCHAR(255), status VARCHAR(20) NOT NULL DEFAULT 'PAID', received_by BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uk_receipt UNIQUE(receipt_number), CONSTRAINT fk_payment_member FOREIGN KEY(member_id) REFERENCES members(id), CONSTRAINT fk_payment_plan FOREIGN KEY(plan_id) REFERENCES membership_plans(id), CONSTRAINT fk_payment_user FOREIGN KEY(received_by) REFERENCES users(id), INDEX ix_payment_date(payment_date), INDEX ix_payment_member(member_id));
CREATE TABLE attendance (id BIGINT AUTO_INCREMENT PRIMARY KEY, member_id BIGINT NOT NULL, checked_in_at TIMESTAMP NOT NULL, checked_out_at TIMESTAMP NULL, status VARCHAR(20) NOT NULL DEFAULT 'CHECKED_IN', source VARCHAR(30) NOT NULL DEFAULT 'MANUAL', recorded_by BIGINT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_att_member FOREIGN KEY(member_id) REFERENCES members(id), CONSTRAINT fk_att_user FOREIGN KEY(recorded_by) REFERENCES users(id), INDEX ix_att_member_time(member_id,checked_in_at), INDEX ix_att_time(checked_in_at));
CREATE TABLE revoked_tokens (jti VARCHAR(64) PRIMARY KEY, expires_at TIMESTAMP NOT NULL, revoked_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX ix_revoked_expiry(expires_at));
CREATE TABLE audit_logs (id BIGINT AUTO_INCREMENT PRIMARY KEY, action VARCHAR(60) NOT NULL, entity_type VARCHAR(60), entity_id VARCHAR(80), actor_user_id BIGINT, actor_username VARCHAR(80) NOT NULL, summary VARCHAR(500), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_audit_actor FOREIGN KEY(actor_user_id) REFERENCES users(id) ON DELETE SET NULL, INDEX ix_audit_actor(actor_username), INDEX ix_audit_action(action), INDEX ix_audit_created(created_at));
